x AS (
SELECT i.lot_id, l.lot_code, l.sticker_raw_upper AS stk, l.status::text AS st, (l.intake_bin_id IS NOT NULL) AS shelf, a.status::text AS ast, l.deleted_at IS NOT NULL AS del,
 (l.status = 'draft' AND l.deleted_at IS NULL AND l.bid_count = 0 AND l.winner_bidder_id IS NULL AND l.current_bid_id IS NULL AND l.relisted_from_lot_id IS NOT NULL AND l.warehouse_id IS NOT NULL AND a.status IN ('closed','canceled')
  AND NOT EXISTS (SELECT 1 FROM bids b WHERE b.lot_id = l.id) AND NOT EXISTS (SELECT 1 FROM invoice_lots il WHERE il.lot_id = l.id)
  AND NOT EXISTS (SELECT 1 FROM lots s WHERE s.id <> l.id AND s.deleted_at IS NULL AND s.status IN ('draft','scheduled','live') AND (s.relisted_from_lot_id = l.relisted_from_lot_id OR s.relisted_from_lot_id = l.id OR s.id = l.relisted_from_lot_id))) AS cap,
 (SELECT string_agg(s.lot_code || ':' || s.status::text, ' ') FROM lots s WHERE s.id <> l.id AND s.deleted_at IS NULL AND s.status::text IN ('in_inventory','pending_intake','won','closed')
   AND (s.relisted_from_lot_id = l.relisted_from_lot_id OR s.relisted_from_lot_id = l.id OR s.id = l.relisted_from_lot_id)) AS kin_held
FROM ids i LEFT JOIN lots l ON l.id = i.lot_id LEFT JOIN auctions a ON a.id = l.auction_id)
SELECT jsonb_build_object('listed',count(*),'exist',count(st),'cap_shelf',count(*) FILTER (WHERE cap AND shelf),'cap_noshelf',count(*) FILTER (WHERE cap AND NOT shelf),'kin_held',count(*) FILTER (WHERE cap AND kin_held IS NOT NULL),'skipped',jsonb_agg(jsonb_build_object('lot',lot_code,'stk',stk,'st',st)) FILTER (WHERE cap IS NOT TRUE)) AS v FROM x
